INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(88, 1, 0, '5', '第 5 章 数组、字符串', 1, 5, '本章围绕数组与字符串展开：先介绍一维数组的声明、创建、初始化与访问、foreach 循环、常用操作、数组作为方法参数与返回值、线性查找与折半查找、冒泡排序、Arrays 类以及数组复制；再介绍二维数组、锯齿二维数组与多维数组，并给出扑克牌混洗和发放、单选题测试评分、矩阵相加三个应用示例；随后讲解 String 类基础与字符串比较、长度、查找、拼接、子字符串、读写、转换等常用处理，介绍文本块、正则表达式及字符串匹配、拆分、替换，并给出回文判断、词频统计、最长公共子串三个应用示例；最后介绍可变长参数列表与命令行参数。', '在编程解决现实世界问题时，经常需要处理大量的数据。例如，假如选修 Java 程序设计课程的学生有 100 人，在考试之后计算他们的平均成绩。在没有学习数组之前，需要 100 个独立变量 score0，score1，....，score99，然后再求和以及计算平均成绩。显然，这种做法是笨拙的且繁琐。当数据量更大时，这种做法是不可行的。于是，Java 语言与其他一些高级程序设计语言均提供了数组来处理这种情况。数组用于存储数据类型相同、元素个数固定、有序数据集合。本章首先介绍一维数组基础知识，包括数组声明、创建、初始化与访问，然后对一维数组常见操作进行讲解，包括一维数组的复制、查找与排序。其次，介绍二维数组的基础概念和常见操作，进一步介绍三维数组和多维数组。然后，举例说明数组作为方法参数和返回值的用法，并对 Arrays 类使用进行介绍。\n另一方面，现实世界经常要处理文本字符，Java 语言处理文本字符的数据类型是字符串。本章首先介绍字符串类型及其常用方法，包括字符串提取、查找、比较、替换和类型转换等。其次，介绍正则表达式及字符串的应用示例。'),
(89, 1, 88, '5.1', '一维数组', 2, 1, NULL, NULL),
(90, 1, 89, '5.1.1', '数组声明与创建', 3, 1, NULL, NULL),
(91, 1, 89, '5.1.2', '数组初始化与访问', 3, 2, NULL, NULL),
(92, 1, 89, '5.1.3', 'foreach 循环', 3, 3, NULL, NULL),
(93, 1, 89, '5.1.4', '数组常用操作', 3, 4, NULL, NULL),
(94, 1, 89, '5.1.5', '数组与方法', 3, 5, NULL, NULL),
(95, 1, 89, '5.1.6', '数组查找', 3, 6, NULL, NULL),
(96, 1, 89, '5.1.7', '数组排序', 3, 7, NULL, NULL),
(97, 1, 89, '5.1.8', 'Arrays 类', 3, 8, NULL, NULL),
(98, 1, 89, '5.1.9', '数组复制', 3, 9, NULL, NULL),
(99, 1, 88, '5.2', '二维数组', 2, 2, '二维数组是具有行下标和列下标的数组，可以用来存储表或矩阵。例如，图 5-8a 给出了一个表用二维数组表示的例子，表是 3 行 3 列的，表示 3 个学生的语文、数学、英语的成绩，对应的二维数组 scores 也是 3 行 3 列的。图 5-8b 给出了一个矩阵用二维数组表示的例子，矩阵也是 3 行 3 列的，对应的二维数组 matrixs 也是 3 行 3 列的。图 5-8 给出的两个示例数组都是 3 行 3 列的，行下标和列下标都是从 0 开始，最大值是 2。（图 5-8　二维数组表示表和矩阵示例：图中 a) 用 int[][] scores = {{78, 89, 95}, {87, 98, 89}, {82, 95, 92}} 表示 3 行 3 列的成绩表；b) 用 int[][] matrixs = {{3, 6, 9}, {4, 5, 7}, {2, 8, 1}} 表示 3 行 3 列的矩阵）', NULL),
(100, 1, 99, '5.2.1', '二维数组声明与创建', 3, 1, NULL, NULL),
(101, 1, 99, '5.2.2', '二维数组初始化与访问', 3, 2, NULL, NULL),
(102, 1, 99, '5.2.3', '锯齿二维数组', 3, 3, NULL, NULL),
(103, 1, 99, '5.2.4', '二维数组处理', 3, 4, NULL, NULL),
(104, 1, 88, '5.3', '多维数组', 2, 3, 'Java 语言把一个二维数组看作是由多个一维数组构成的数组，而一个三维数组是由多个二维数组构成的数组，每个二维数组又是由多个一维数组构成的数组。一个四维数组是由多个三维数组构成数组。因此，可以总结为：一个 n（n≥ 2）维数组可以看作是由多个 n-1 维数组构成的数组。', NULL),
(105, 1, 88, '5.6', '数组应用示例', 2, 4, NULL, NULL),
(106, 1, 105, '5.6.1', '扑克牌混洗和发放', 3, 1, NULL, NULL),
(107, 1, 105, '5.6.2', '单选题测试评分', 3, 2, NULL, NULL),
(108, 1, 105, '5.6.3', '矩阵相加', 3, 3, NULL, NULL),
(109, 1, 88, '5.7', '字符串', 2, 5, '在本节之前，本教材的一些示例已经使用了字符串字面量和 String 类。在 Java 语言中，字符串是由一对双引号括起来的 Unicode 字符序列。字符串字面量，如"Hello world!"，就是一个 String 类的对象，本节主要介绍 String 类及字符串的一些常见处理。', NULL),
(110, 1, 109, '5.7.1', 'String 类基础', 3, 1, NULL, NULL),
(111, 1, 109, '5.7.2', '字符串处理', 3, 2, NULL, NULL),
(112, 1, 109, '5.7.3', '文本块(Text Blocks)', 3, 3, NULL, NULL),
(113, 1, 88, '5.8', '正则表达式', 2, 6, '一些应用程序具有验证用户输入的需求，例如，一个应用程序要求用户输入一个手机号，那么该程序就应该要验证输入的字符是否数字，是否 11 位。如何编写代码来验证用户的输入呢？通常，一个有效的做法就是使用正则表达式（Regular Expression，简写为 regex）', NULL),
(114, 1, 113, '5.8.1', '字符串匹配', 3, 1, NULL, NULL),
(115, 1, 113, '5.8.2', '字符串拆分', 3, 2, NULL, NULL),
(116, 1, 113, '5.8.3', '字符串替换', 3, 3, NULL, NULL),
(117, 1, 88, '5.9', '字符串应用示例', 2, 7, NULL, NULL),
(118, 1, 117, '5.9.1', '回文判断', 3, 1, NULL, NULL),
(119, 1, 117, '5.9.2', '词频统计', 3, 2, NULL, NULL),
(120, 1, 117, '5.9.3', '最长公共子串', 3, 3, NULL, NULL),
(121, 1, 88, '5.10', '可变长参数列表', 2, 8, 'Java 语言在定义方法时，允许方法有且仅有一个可变长参数，并且可变长参数是该方法的最后一个参数。可变长参数的声明形式如下：', NULL),
(122, 1, 88, '5.11', '命令行参数', 2, 9, 'Java 应用程序执行的入口方法是 main 方法，它具有一个 String[]类型的形参 args，是一个字符串数组。在前述学习过程中，main 方法始终是调用其他方法的。那么 main 方法是可以像带参数的普通方法一样被调用呢？当然是可以的。程序清单 5-23、程序清单 5-24 给出了一个示例。', NULL),
(123, 1, 88, '5.12', '课程思政', 2, 10, '对应章节：第五章 引言部分：为什么引入数组', NULL);
