INSERT INTO `knowledge_concept` (`id`, `chapter_id`, `name`, `definition`, `difficulty`, `page`, `page_order`) VALUES
(208, 90, '数组', '数组表示数据类型相同、元素个数固定的有序数据集合，是一个引用数据类型。', 1, 166, 1),
(209, 90, '数组下标运算符', '数据类型既可以是基本数据类型，也可以是引用类型。其后接着一对方括号[]，[]是数组下标运算符。', 1, 166, 2),
(210, 90, '数组长度', '其中，数组长度是一个整数值（整型字面量或整型常量）或能计算出确定整数值的表达式。在创建数组时，必须指定数组长度。数组长度指定了该数组可存储的数组元素个数。', 1, 166, 3),
(211, 91, '数组初始化', '数组在创建之后，通常要进行初始化操作，给每个数组元素赋初值。', 1, 166, 1),
(212, 91, '初始化列表', '其中，由一对花括号括起来的、多个逗号分隔的值的列表，称为初始化列表。', 1, 167, 1),
(213, 91, '数组长度固定不可修改', '在创建数组后，数组长度是固定的，且不能被修改，可以使用“数组变量名.length”得到数组长度。', 1, 167, 2),
(214, 91, '数组元素的默认值', '数组元素类型是整数类型（byte、short、int 和 long）时，默认值是 0。', 1, 167, 3),
(215, 91, '引用类型数组元素的默认值', '数组元素类型是引用类型（类、接口和数组）时，默认值是 null。', 1, 167, 4),
(216, 92, 'foreach 循环', 'Java 语言提供了一种称为 foreach 循环的简洁 for 循环，可以用来按顺序遍历数组中的每个元素，而不必考虑数组下标值。', 1, 169, 1),
(217, 94, '匿名数组', '这种方式传递的是一个匿名数组，这里使用 new 操作符和初始化列表创建了一个数组，该数组没有显式的数组变量名引用它。', 1, 172, 1),
(218, 94, '数组的参数传递', '无论给方法传递的是基本数据类型值还是数组引用类型值，都是把实参的值赋值形参变量。然而，当把引用值传递给形参之后，形参和实参会引用同一个内存区域。', 1, 172, 2),
(219, 94, '内存堆', '而数组是一个引用类型，JVM 将数组的具体内容存储在称为内存堆的内存区域。内存堆用于动态分配内存。', 1, 173, 1),
(220, 94, '数组作为方法返回值类型', '当方法的返回值类型是一个数组类型时，方法可以返回一个数组。方法返回一个数组，实际上返回的是一个数组的引用。', 1, 175, 1),
(221, 95, '线性查找', '线性查找又称为顺序查找，是一种最简单的查找方法。', 1, 176, 1),
(222, 95, '线性查找的基本思想', '将要查找的关键字 key 值与数组中的元素依次逐个比较，直到找到与 key 值相等的元素，或者查找完数组没有找到与之相等的元素。如果找到与 key 值相等的元素，则返回该数组元素对应的下标值。否则，返回-1。', 1, 176, 2),
(223, 95, '折半查找', '折半查找又称为二分查找（binary search），是一种在有序数组中查找某一特定元素的搜索算法。使用折半查找的前提是数组中的元素必须是已经排好序的。', 1, 177, 1),
(224, 95, '折半查找的下标变量', '为了便于描述折半查找过程，需设计三个下标变量：high、low、mid，它们分别表示当前待查找数组的最后一个元素下标、第一个元素的下标、中间元素的下标。', 1, 177, 2),
(225, 96, '冒泡排序', '冒泡排序的基本思想是：从下标为 0 的元素开始，依次比较两个相邻的元素；如果前者大于后者，就交换这两个相邻元素的值。', 1, 179, 1),
(226, 96, '冒泡排序的趟数', '因此，在冒泡排序中，下一趟比较比上一趟比较会减少比较次数，并找出无序区域的最大值。', 1, 179, 2),
(227, 97, 'Arrays 类', 'java.utils.Arrays 类提供了对数组操作的一系列方法，使用这些方法可以简化开发过程，提高开发效率。', 1, 181, 1),
(228, 97, '二分查找的插入点', '用二分查找算法在给定数组 a 中查找给定值 key，数组 a 在调用前必须是已经排序的。如果找到，则返回对应数组元素的下标值；如果在数组中找不到 key 值，则返回：(- (插入点的下标值) - 1)。', 1, 181, 2),
(229, 97, 'Arrays 类的静态方法', 'java.util.Arrays 类提供的方法通常都是静态的，通过类名可以直接进行调用。', 1, 181, 3),
(230, 98, '数组深度复制', '在 Java 语言中，数组复制可以分为深度复制和浅度复制，数组的深度复制是复制数组的内容，而浅度复制是复制数组的引用。', 1, 182, 1),
(231, 98, 'copyOf() 方法', '复制指定的数组 original，截断或填充零（如有必要），使副本具有指定的长度 newLength。对于在原始数组和副本中都有效的所有索引，这两个数组将包含相同的值。', 1, 183, 1),
(232, 98, 'copyOfRange() 方法', '将指定数组 original 的指定范围复制到新数组中。范围的初始索引（from）必须介于零和 original.length 之间，包括零和 orional.length。', 1, 183, 2),
(233, 98, 'arraycopy() 方法', '从指定源数组 src 的指定位置 srcPos 开始，将数组复制到目标数组 dest 的指定位置 destPos。数组元素的子序列从 src 引用的源数组复制到 dest 引用的目标数组。复制的数组元素数量等于长度参数 length。', 1, 183, 3),
(234, 99, '二维数组', '二维数组是具有行下标和列下标的数组，可以用来存储表或矩阵。', 1, 184, 1),
(235, 99, '二维数组由一维数组构成', 'Java 语言把二维数组看作是由多个一维数组构成的数组。', 1, 184, 2),
(236, 101, '二维数组的长度', '二维数组的每一个元素是一个一维数组。二维数组的长度表示其包含多少个一维数组，例如，二维数组 scores 包含三个一维数组，因此，scores.length 的值为 3。', 1, 185, 1),
(237, 102, '锯齿二维数组', 'Java 语言的二维数组是由多个一维数组构成，各个一维数组的长度可以不相同。这种数组可以称为锯齿二维数组，还可以称为不规则二维数组。锯齿数组也可以扩展到多维数组。', 1, 186, 1),
(238, 103, '二维数组处理', '由于二维数组的长度是固定的，所以常常使用嵌套 for 循环处理二维数组。', 1, 187, 1),
(239, 104, '多维数组', 'Java 语言把一个二维数组看作是由多个一维数组构成的数组，而一个三维数组是由多个二维数组构成的数组，每个二维数组又是由多个一维数组构成的数组。', 1, 189, 1),
(240, 104, '三维数组的下标层次', '对于三维数组 grades，可以看作是由 5 个二维数组构成，每个二维数组可以看作是由 3 个一维数组构成。', 1, 189, 2),
(241, 106, '数组下标与扑克牌的映射', '一副扑克牌在去掉大王、小王两张扑克牌后，剩下 52 张，由黑桃、红桃、梅花、方块 4 种花色构成，每种花色的牌有 13 张。可以用一维数组存储表示 52 张扑克牌，并设计好数组下标与扑克牌之间的映射关系。', 1, 191, 1),
(242, 107, '单选题测试评分的数组设计', '学生答题表可以用一个二维数组表示，正确答案可用一个一维数组表示，每个学生的学号用一个一维数组表示，每个学生的成绩也用一个一维数组表示。', 1, 193, 1),
(243, 108, '矩阵相加', '矩阵相加运算要求两个矩阵必须具备相同的维数。', 1, 194, 1),
(244, 110, '字符串', '在 Java 语言中，字符串是由一对双引号括起来的 Unicode 字符序列。', 1, 196, 1),
(245, 110, '字符串字面量', '字符串字面量，如"Hello world!"，就是一个 String 类的对象', 1, 196, 2),
(246, 110, 'String 类', 'Java 语言提供了 String 类来创建和操作字符串', 1, 196, 3),
(247, 110, '字符串常量池', 'JVM 为字符串字面量维护了一个字符串常量池（String constant pool），每当代码中出现一个字符串字面量，JVM 首先会查询字符串常量池。如果字符串已经在常量池中，就将该字符串的引用返回给字符串引用变量。否则，就创建一个字符串并放置于常量池。', 1, 196, 4),
(248, 110, '字符串不可变', '在 Java 语言中，字符串是不可变且使用频率高，因此，JVM 为了提高效率并节约内存，对具有相同 Unicode 字符序列的字面量使用同一个实例。', 1, 196, 5),
(249, 111, '字符串比较', '在比较两个字符串时，如果想比较两个字符串内容是否相等，那么需要使用 equals()方法。如果想比较两个字符串是否同一个对象，可以使用==运算符。', 1, 197, 1),
(250, 111, 'equalsIgnoreCase() 方法', 'Java 语言是大小写敏感的语言，当需要忽略字母大小写进行比较时，可以使用 equalsIgnoreCase() 方法。', 1, 198, 1),
(251, 111, 'compareTo() 方法', 'Java 语言提供了 compareTo()方法按字典序比较两个字符串，确定谁大、谁小或相等。', 1, 198, 2),
(252, 111, '字典序比较规则', '在比较时，按字典顺序从左往右将 str 表示的字符序列与 cmpStr 参数表示的字符序列逐个进行比较。', 1, 198, 3),
(253, 111, 'length() 方法', 'String 类获取字符串长度的方法是 length()，返回字符串对象包含的字符数。', 1, 198, 4),
(254, 111, 'charAt() 方法', 'String 类的方法 public char charAt(int index)，返回字符串指定位置 index 的字符(index 从 0 开始，最大值为：字符串长度-1)。', 1, 198, 5),
(255, 111, 'toCharArray() 方法', 'String 类的方法 public char[] toCharArray()可以基于字符串的内容生成一个字符数组并返回', 1, 198, 6),
(256, 111, 'indexOf(String str)', '在此字符串中，从左向右查找指定字符串的位置，若找不到返回-1', 1, 199, 1),
(257, 111, 'contains() 方法', '判断此字符串是否包含子字符串 s，若包含返回 true，否则返回 false', 1, 199, 2),
(258, 111, 'endsWith() 方法', '判断此字符串是否以指定的字符串 suffix 结尾，若是，则返回 true；否则返回 false', 1, 199, 3),
(259, 111, '字符串拼接', 'Java 编译器为方便字符串操作，允许使用运算符+连接任意字符串和其他数据类型值，这样极大地方便了字符串的处理。', 1, 199, 4),
(260, 111, 'concat() 方法', 'String 类有一个方法 public String concat(String str)，其作用是连接多个字符串', 1, 200, 1),
(261, 111, 'join() 静态方法', '如果需要将多个字符串拼接在一起，并用一个界定符分隔，可以使用 String 类的静态方法 join()', 1, 200, 2),
(262, 111, 'repeat() 方法', '从 Java SE 11 开始，Java 语言提供了 repeat 方法，对相同字符串重复拼接', 1, 200, 3),
(263, 111, '字面值直接拼接与常量池', '上述字符串拼接的结果，只有字符串字面值直接拼接的结果才能使用字符串常量池中的字符串对象，其他情况下，通过变量名称的拼接或方法的拼接都需要创建新的字符串对象。', 1, 200, 4),
(264, 111, 'substring() 方法', '子字符串从指定的 beginIndex 开始，并扩展到索引 endIndex - 1 处的字符。因此，子字符串的长度是 endIndex - beginIndex。', 1, 200, 5),
(265, 111, 'next() 方法', 'Scanner 类的 next()方法从控制台读取字符串时，如果字符串中包含空格，只会获取第一个空格之前的子串作为读取的字符串。', 1, 201, 1),
(266, 111, 'nextLine() 方法', 'Scanner 类的 nextLine()方法从控制台读取字符串时，字符串中可以包含空格，遇到回车符才结束。', 1, 201, 2),
(267, 111, 'trim() 方法', 'trim()方法返回一个字符串，该字符串的值为此字符串，去掉所有的前导和尾部空格。', 1, 201, 3),
(268, 111, 'toLowerCase() 与 toUpperCase() 方法', 'toLowerCase()将此字符串中的字符全部转换为小写，生成一个新字符串返回；toUpperCase()将此字符串中的字符全部转换成大写，生成一个新字符串返回。', 1, 201, 4),
(269, 111, 'valueOf() 方法', '当需要把基本类型值转换为字符串时，可以使用 String 类的静态方法 public static String valueOf(基本数据类型 变量名)。方法 valueOf()是一个重载方法，Java 编译器会根据参数的数据类型匹配合适的方法。', 1, 201, 5),
(270, 112, '文本块', '文本块是一种多行字符串文字，它以三个双引号字符 (""")开始，以三个双引号字符 (""")结束。', 1, 202, 1),
(271, 112, '文本块的缩进规则', '文本块支持缩进，提升阅读的清晰性；Java 编译器在处理文本块缩进时，会自动删除不需要的缩进：每行结尾的空格都会删除；每行开始的共有的空格会自动删除；只保留相对缩进。', 1, 202, 2),
(272, 112, '文本块引入的主要原因', '该代码段通常难以阅读且难以维护，因此，如果具有一种机制，可以比多行文字更直观地表示字符串，而且可以跨越多行，而且不会出现转义的视觉混乱，那么这将提高广泛 Java 类程序的可读性和可写性。', 1, 202, 3),
(273, 113, '正则表达式', '正则表达式是由普通字符以及特殊符号组成的一个字符串，用来描述匹配一个字符串集合的模式。对于字符串处理而言，正则表达式也是一个强大的工具，用于匹配、替换或拆分字符串。', 1, 203, 1),
(274, 113, '正则表达式中的反斜杠转义', '注意：正则表达式中\\d，在字符串的双引号内表示时，需要使用两个反斜杠，例如，“\\\\d”。', 1, 204, 1),
(275, 114, 'matches() 方法', 'String 类的 match 方法：public boolean matches(String regex)，用于表示此字符串是否匹配给定的正则表达式 regex。', 1, 204, 1),
(276, 115, 'split() 方法', '使用 String 类的 split()方法结合正则表达式，可以对一个字符串进行拆分', 1, 205, 1),
(277, 115, 'split() 方法的 limit 参数', '基于给定正则表达式的匹配项对字符串进行拆分，返回字符串数组，limit 参数确定模式匹配多少次，最后返回的字符串数组长度由 limit 决定', 1, 205, 2),
(278, 116, 'replaceAll() 与 replaceFirst() 方法', 'String 类的 replaceAll、replaceFirst 可以和正则表达式一起使用', 1, 205, 1),
(279, 116, 'replace() 方法', '将目标字符序列替换成第二个参数位置上的字符序列，返回新的字符串，不支持正则表达式', 1, 205, 2),
(280, 116, '正则表达式分组引用', '这里，$1、$2、 $3 分别对应正则表达式 3 个部分\\\\d{3}、\\\\d{4}、\\\\d{4}，在 replaceAll 方法中，"$1****$3"表示第一个部分、第三个部分保持不变，中间部分用****替换。', 1, 206, 1),
(281, 118, '回文', '一个字符串如果从左向右读和从右向左读是一样的，这个字符串被称为回文(Palindrome)，例如，“level”、“noon”、“dad”、“mom”都是回文；而“text”、“this”等都不是回文。', 1, 206, 1),
(282, 118, '回文判断的比较次数', '如果字符串长度为 length，那么比较次数就是 length/2(整数除法)。当 length 是奇数时，中间字符无需比较。', 1, 206, 2),
(283, 119, '词频统计', '在字符串处理过程中，有时候需要统计某些各个单词在一篇文章中出现的次数。', 1, 207, 1),
(284, 120, '最长公共子串', '最长公共子串问题是一个经典的编程问题：给定两个字符串，输出它们最长公共子串的长度。', 1, 209, 1),
(285, 120, '公共子串的连续性要求', '最长公共子串要求子串在原字符串中是连续的，例如，字符串“bab”和“bcaba”，其中“ba”或者“ab”是公共子串而“bab”不是公共子串。', 1, 209, 2),
(286, 121, '可变长参数', 'Java 语言在定义方法时，允许方法有且仅有一个可变长参数，并且可变长参数是该方法的最后一个参数。', 1, 210, 1),
(287, 121, '可变长参数的处理', '可变长参数可以接收一个数组或不定数目的参数，被 Java 语言作为一个数组来处理。当传递不定数目的参数调用方法时，Java 编译器会创建一个数组容纳参数，然后将这个数组传递给形参。', 1, 210, 2),
(288, 121, '可变长参数与数组形参的等价性', '虽然 double…与 double[]貌似不一样，但 Java 编译器把它们看做 double 类型数组。', 1, 211, 1),
(289, 122, '命令行参数', 'Java 应用程序执行的入口方法是 main 方法，它具有一个 String[]类型的形参 args，是一个字符串数组。', 1, 211, 1),
(290, 122, '命令行参数中的空格处理', '命令行中的字符串参数通常是不需要双引号的，如果一个字符串中包含空格，那么这个字符串必须加双引号', 1, 212, 1),
(291, 123, '个体与集体的关系', '讲解完为什么引入数组时，引申说明单个变量就像个体一样，其作用存在局限性。当使用数组把原本独立的变量组织在一起，发挥集体优势，便于处理大规模问题。', 1, 214, 1);
INSERT INTO `knowledge_code_snippet` (`id`, `chapter_id`, `title`, `code`, `is_key_example`, `page`, `page_order`) VALUES
(169, 90, '一维数组声明的两种语法形式', '数据类型[] 数组变量名; //形式 1，推荐形式\n数据类型 数组变量名[]; //形式 2', 0, 166, 1),
(170, 90, '声明 int 类型数组的两种写法', 'int[] firstArray; //推荐形式\nint firstArray[];', 0, 166, 2),
(171, 90, '使用 new 操作符创建一维数组的一般形式', '数组变量名 = new 数据类型 [数组长度];', 0, 166, 3),
(172, 90, '创建含 5 个元素的 int 类型数组示例', 'firstArray = new int[5];', 0, 166, 4),
(173, 90, '声明、创建一步完成的一维数组语法形式', '数据类型[] 数组变量名 = new 数据类型 [数组长度]; //形式 1\n数据类型 数组变量名[] = new 数据类型 [数组长度]; //形式 2', 0, 166, 5),
(174, 90, '声明并创建含 5 个元素的 int 数组的两种写法', 'int[] firstArray = new int[5]; //或\nint firstArray[] = new int[5];', 0, 166, 6),
(175, 91, '按下标为数组元素赋值的一般形式', '数组变量名[下标值] = 值;', 0, 166, 7),
(176, 91, '逐元素初始化 firstArray 数组的语句', 'firstArray[0] = 10;\nfirstArray[1] = 20;\nfirstArray[2] = 30;\nfirstArray[3] = 40;\nfirstArray[4] = 50;', 0, 167, 8),
(177, 91, '用初始化列表一步完成声明、创建、初始化的语法形式', '数据类型[] 数组变量名 = {值 1,值 2, 值 3, …, 值 n}; //或\n数据类型 数组变量名[] = {值 1,值 2, 值 3, …, 值 n};', 0, 167, 9),
(178, 91, '用初始化列表创建 int 数组示例', 'int[] firstArray = {10, 20, 30, 40, 50};', 0, 167, 10),
(179, 91, '初始化列表末尾加逗号的合法与非法写法', 'int[] array1 = {};   //合法，长度为零的数组\nint[] array2 = {,};  //合法，长度为零的数组\nint[] array3 = {2, 3}; //合法，长度为 2 的数组\nint[] array4 = {2, 3, }; //合法，长度为 2 的数组\nint[] array5 = {2, 3, ,}; //不合法，Java 编译器报错', 0, 167, 11),
(180, 91, '程序清单 5-1　FirstArrayDemo.java', '1  public class FirstArrayDemo {\n2  public static void main(String[] args) {\n3      int[] myArray = new int[5];\n4     System.out.printf("myArray 的长度：%d\\n", myArray.length);\n5     System.out.print("myArray 默认值：");\n6     for(int i = 0; i < myArray.length; i++)\n7     System.out.printf("%-4d", myArray[i]);\n8     //初始化数组\n9     for(int i = 0; i < myArray.length; i++)\n10    myArray[i] = i*i;\n11    //输出初始化后的数组元素值\n12    System.out.print("\\nmyArray 初始化后：");\n13    for(int i = 0; i < myArray.length; i++)\n14    System.out.printf("%-4d", myArray[i]);\n15    //初始化列表创建数组\n16    int[] nextArray = {8, 3, 6, 17, 9, 15};\n17    System.out.print("\\nnextArray：");\n18    for(int i = 0; i < nextArray.length; i++)\n19    System.out.printf("%-4d", nextArray[i]);\n20 }\n21 }', 0, 167, 12),
(181, 91, '程序清单 5-1 运行结果', 'myArray 默认值： 0 0 0 0 0\nmyArray 初始化后： 0 1 4 9 16\nnextArray： 8 3 6 17 9 15', 0, 168, 13),
(182, 91, '先声明数组变量、再创建并初始化的一般形式', '数据类型[] 数组变量;\n数组变量 = new 数据类型[]{值 1, 值 2,…, 值 n};', 0, 168, 14),
(183, 91, '程序清单 5-2　TestArrayRef 程序代码', '1  public class TestArrayRef {\n2     public static void main(String[] args) {\n3     int[] ns; // 声明一个 int 类型数组\n4     //创建、初始化一步完成\n5     ns = new int[] { 68, 79, 91, 85, 62 };\n6     System.out.print("ns 第一次赋值后：");\n7     for(int i = 0; i < ns.length; i++)\n8     System.out.printf("%-4d", ns[i]);\n9     //修改 ns\n10    ns = new int[] { 1, 2, 3 };\n11    System.out.print("\\nns 第二次赋值后：");\n12    for(int i = 0; i < ns.length; i++)\n13        System.out.printf("%-4d", ns[i]);\n14 }\n15 }', 0, 168, 15),
(184, 91, '程序清单 5-1 运行结果', 'ns 第一次赋值后：68 79 91 85 62\nns 第二次赋值后：1 2 3', 0, 169, 16),
(185, 92, 'foreach 循环的一般语法形式', 'for(数据类型 变量名: 数组变量名){\n      //循环体处理语句\n}', 0, 169, 17),
(186, 92, '用 foreach 循环按顺序输出数组元素', 'for(int e: myArray) // 可以读作：对数组 myArray 中的每个元素 e\n      System.out.printf("%4d", e);', 0, 169, 18),
(187, 93, '程序清单 5-3　HandleArrayDemo.java', '1  public class HandleArrayDemo {\n2   public static void main(String[] args) {\n3   //创建两个测试数组\n4   int[] intList = new int[5];\n5   double[] dList = new double[10];\n6   //1、用输入值初始化数组\n7   System.out.printf("请输入%d 个整数：", intList.length);\n8   Scanner input = new Scanner(System.in);\n9   for(int i = 0; i < intList.length; i++)\n10  intList[i] = input.nextInt();\n11  System.out.print("intList 的当前值：");\n12  //2、输出数组元素\n13  for(int e: intList)\n14  System.out.print(e + " ");\n15\n16  //3、使用随机值初始化数组\n17  for(int i = 0; i < dList.length; i++)\n18  dList[i] = 100 * Math.random();\n19\n20  System.out.println("\\ndList 的当前值：");\n21  //输出数组元素\n22  for(double e: dList)\n23  System.out.printf("%-6.2f",e);\n24\n25  //4、对所有元素求和\n26  double sum = 0.0;\n27  for(double e: dList)\n28  sum += e;\n29  System.out.printf("\\ndList 所有元素的和：%.2f\\n", sum);\n30\n31  //5、找出数组最大值\n32  double max = dList[0];\n33  for(double e: dList) {\n34  if(e > max)\n35  max = e;\n36    }\n37    System.out.printf("dList 的最大值=%.2f\\n", max);\n38\n39    //6、找出数组最小值及其下标\n40    double min = dList[0];\n41    int minIndex = 0;\n42    for(int i = 0; i < dList.length; i++) {\n43       if(dList[i] < min) {\n44              min = dList[i];\n45              minIndex = i;\n46       }\n47    }\n48    System.out.printf("dList 的最小值=%.2f，对应下标=%d\\n", min, minIndex);\n49\n50    //7、随机打乱\n51    for(int i = 0; i < intList.length; i++) {\n52       int k = (int)(Math.random()*intList.length);\n53       int temp = intList[i];\n54       intList[i] = intList[k];\n55       intList[k] = temp;\n56    }\n57    System.out.print("intList 打乱后的值：");\n58    for(int e: intList)\n59       System.out.print(e + " ");\n60\n61    //8、向右移动一位元素，将最后一位元素移动到起始位置\n62    int temp = intList[intList.length - 1];\n63    for(int i = intList.length - 1; i >= 1; i--)\n64       intList[i] = intList[i - 1];\n65    intList[0] = temp;\n66    System.out.print("\\nintList 右移一位后：");\n67    for(int e: intList)\n68       System.out.print(e + " ");\n69 }\n70 }', 0, 170, 19),
(188, 93, '程序清单 5-3 运行结果', '请输入 5 个整数：3 5 7 9 11\nintList 的当前值：3 5 7 9 11\ndList 的当前值：\n6.05 33.99 42.33 65.65 47.53 61.72 81.83 43.41 89.64 45.44\ndList 所有元素的和：517.59\ndList 的最大值=89.64\ndList 的最小值=6.05，对应下标=0\nintList 打乱后的值：11 3 5 9 7\nintList 右移一位后：7 11 3 5 9', 0, 171, 20),
(189, 94, '以 int 数组为形参的 displayArray 方法', 'public static void displayArray(int[] list){\n      for(int e: list)\n            System.out.printf("%d, ", e);\n}', 0, 172, 21),
(190, 94, '待传递的 int 类型数组 list1', 'int[] list1 = {3, 5, 7};', 0, 172, 22),
(191, 94, '以数组变量作为实参调用方法', 'displayArray(list1); //输出 3, 5, 7,', 0, 172, 23),
(192, 94, '以匿名数组作为实参调用方法', 'displayArray(new int[]{3, 5, 7}); //输出 3, 5, 7,', 0, 172, 24),
(193, 94, '程序清单 5-4　TestArrayMethod1.java', '1  public class TestArrayMethod1 {\n2   public static void modify(int num,int[] list){\n3      num = 0;\n4      list[0] = -1;\n5   }\n6   public static void main(String[] args) {\n7      int number = 9;\n8      int[] list = {1, 3, 5};\n9      System.out.printf("方法调用前,number=%d,ilist[0]=%d\\n",\n10              num, list[0]);\n11     modify(num, list);\n12     System.out.printf("方法调用后,number=%d,ilist[0]=%d",\n13              num, list[0]);\n14  }\n15 }', 0, 173, 25),
(194, 94, '程序清单 5-4 运行结果', '方法调用前,number=9,ilist[0]=1\n方法调用后,number=9,ilist[0]=-1', 0, 173, 26),
(195, 94, '程序清单 5-5　TestSwapTwoNums.java', '1  public class TestSwapTwoNums {\n2     //交换两个整数的值\n3     public static void swap(int num1, int num2) {\n4        int temp = num1;\n5        num1 = num2;\n6        num2 = temp;\n7     }\n8     //将一个整数数组的首尾元素的值进行交换\n9     public static void swap(int[] nums) {\n10       int temp = nums[0];\n11       nums[0] = nums[nums.length-1];\n12       nums[nums.length-1] = temp;\n13 }\n14 //输出数组\n15 public static void showArray(int[] nums) {\n16       System.out.print("数组元素：");\n17       for(int e:nums)\n18       System.out.print(" " + e);\n19 }\n20 public static void main(String[] args) {\n21       int[] ilist = {1, 3, 5, 7};\n22\n23       System.out.println("在调用方法之前：");\n24       showArray(ilist);\n25\n26       System.out.println("\\n 在调用 swap(int,int)后：");\n27       swap(ilist[0],ilist[ilist.length-1]);\n28       showArray(ilist);\n29\n30       System.out.println("\\n 在调用 swap(int[])后：");\n31       swap(ilist);\n32       showArray(ilist);\n33 }\n34 }', 0, 174, 27),
(196, 94, '程序清单 5-5 运行结果', '在调用方法之前：\n数组元素： 1 3 5 7\n在调用 swap(int,int)后：\n数组元素： 1 3 5 7\n在调用 swap(int[])后：\n数组元素： 7 3 5 1', 0, 174, 28),
(197, 94, '程序清单 5-6　TestReturnArray.java', '1  public class TestReturnArray {\n2     public static int[] filterScore(int[] scores) {\n3        int count = 0;\n4        for(int e: scores)\n5        if(e >= 60)\n6                    count++;\n7        int[] sList = new int[count];\n8        int j = 0;\n9        for(int i = 0; i < scores.length; i++)\n10       if(scores[i] >= 60) {\n11                   sList[j] = scores[i];\n12                   j++;\n13       }\n14       return sList;\n15    }\n16    //输出数组\n17    public static void showArray(int[] nums) {\n18       for(int e:nums)\n19       System.out.print(" " + e);\n20    }\n21    public static void main(String[] args) {\n22       int[] scores = {55, 75, 65, 85, 45, 92, 58};\n23       System.out.println("原始成绩单：");\n24       showArray(scores);\n25       //返回一个数组\n26       int[] passList = filterScore(scores);\n27       System.out.println("\\n 去除不及格后的成绩单：");\n28       showArray(passList);\n29    }\n30 }', 0, 175, 29),
(198, 94, '程序清单 5-6 运行结果', '原始成绩单：\n  55 75 65 85 45 92 58\n去除不及格后的成绩单：\n  75 65 85 92', 0, 175, 30),
(199, 95, '程序清单 5-7　LinearSearch.java', '1  public class LinearSearch {\n2   //线性查找算法，在数组 nums 中查找与 key 相等的元素\n3   public static int linearSearching(int[] nums, int key) {\n4      for(int i = 0; i < nums.length; i++)\n5           if(nums[i] == key)\n6                  return i;\n7      return -1;\n8   }\n9   public static void main(String[] args) {\n10     int[] ilist = {1, 3, 3, 5, 5, 7, 9, 7};\n11     System.out.println("查找 5，返回：" + linearSearching(ilist, 5));\n12     System.out.println("查找 4，返回：" + linearSearching(ilist, 4));\n13     System.out.println("查找 7，返回：" + linearSearching(ilist, 7));\n14  }\n15 }', 0, 176, 31),
(200, 95, '程序清单 5-7 运行结果', '查找 5，返回：3\n查找 4，返回：-1\n查找 7，返回：5', 0, 176, 32),
(201, 95, '程序清单 5-8　HalfIntervalSearch.java', '1  public class HalfIntervalSearch {\n2   //折半查找方法\n3   public static int halfSearch(int[] nums, int key) {\n4      int low = 0;                        //第一个元素下标\n5      int high = nums.length - 1; //最后一个元素下标\n6\n7      //low >= high 时，表示查找完整个数组\n8      while(low < high) {\n9           int mid = (low + high) / 2; //中间元素下标\n10          if(key == nums[mid])\n11                return mid; //查找成功，返回 mid，方法结束\n12          else if(key < nums[mid] )\n13                high = mid - 1;\n14          else                     //key 大于中间元素值\n15                low = mid + 1;\n16     }\n17     return -1; //上述循环没有找到 key，返回-1\n18  }\n19\n20  public static void main(String[] args) {\n21     int[] ilist = {1, 3, 5, 9, 12, 23, 34, 39, 56, 78};\n22     System.out.println("查找 5，返回：" + halfSearch(ilist, 5));\n23     System.out.println("查找 56，返回：" + halfSearch(ilist, 56));\n24     System.out.println("查找 2，返回：" + halfSearch(ilist, 2));\n25  }\n26 }', 0, 178, 33),
(202, 95, '程序清单 5-8 运行结果', '查找 5，返回：2\n查找 56，返回：8\n查找 58，返回：-1', 0, 178, 34),
(203, 96, '程序清单 5-9　BubbleSort.java', '1  public class BubbleSort {\n2   //冒泡排序算法实现\n3   public static void bubbleSorting(int[] nums) {\n4     for (int i = 0; i < nums.length - 1; i++) {//最多 n-1 趟比较\n5        boolean flag = false; //有无交换发生的标志变量\n6        for (int j = 0; j < nums.length - i - 1; j++) {\n7              //每趟两两比较完后，增大一个有序区域\n8            if (nums[j] > nums[j+1]) {\n9                    int temp = nums[j];\n10                   nums[j] = nums[j+1];\n11                   nums[j+1] = temp;\n12                   flag = true; //交换发生，flag 置为 true\n13           }\n14       }\n15       if(!flag) //当不存在交换时，结束比较\n16              return;\n17    }\n18 }\n19 public static void showArray(int[] a) {\n20    for(int e: a)\n21       System.out.print(e + " ");\n22 }\n23 public static void main(String[] args) {\n24    int[] a = {14, 17, 29, 26, 35, 12, 24};\n25    System.out.print("排序前：");\n26    showArray(a);\n27    //排序\n28    bubbleSorting(a);\n29    System.out.print("\\n 排序后：");\n30    showArray(a);\n31 }\n32 }', 0, 180, 35),
(204, 96, '程序清单 5-9 运行结果', '排序前：14 17 29 26 35 12 24\n排序后：12 14 17 24 26 29 35', 0, 180, 36),
(205, 97, '程序清单 5-10　ArraysDemo1.java', '1  public class ArraysDemo1 {\n2          public static void main(String[] args) {\n3          int[] a = {24, 35, 21, 46, 18, 56, 42, 39};\n4          int[] b =null, c=null;\n5          System.out.println("数组 a 排序前：" + Arrays.toString(a));\n6          //排序\n7          Arrays.sort(a);\n8          System.out.println("数组 a 排序后：" + Arrays.toString(a));\n9          //查找\n10         System.out.println("在数组 a 中，折半查找 42，返回：" +\n11               Arrays.binarySearch(a, 42));\n12         System.out.println("在数组 a 中，折半查找 45，返回：" +\n13               Arrays.binarySearch(a, 45));\n14         //比较两个数组\n15         System.out.println("b == c ? " + Arrays.equals(b, c));\n16\n17         b = new int[5];\n18         c = new int[5];\n19    Arrays.fill(b, 1);\n20    Arrays.fill(c, 2);\n21    System.out.println("数组 b：" + Arrays.toString(b));\n22    System.out.println("数组 c：" + Arrays.toString(c));\n23    System.out.println("b == c ? " + Arrays.equals(b, c));\n24 }\n25 }', 0, 181, 37),
