(224, 103, '程序清单 5-12　TestTwoDArray.java', '1  public class TestTwoDArray {\n2   public static void main(String[] args) {\n3   int[][] matrix1 = new int[5][5];\n4   int[][] matrix2 = new int[2][2];\n5   //1.使用随机值初始化数组\n6   for(int i = 0; i < matrix1.length; i++)\n7      for(int j = 0; j < matrix1[i].length; j++)\n8      matrix1[i][j] = (int)(Math.random()*100);\n9   //2.使用输入值初始化数组\n10  Scanner input = new Scanner(System.in);\n11  System.out.println("请输入" + matrix2.length + "行"\n12     + matrix2[0].length + "列整数：");\n13  for(int i = 0; i < matrix2.length; i++)\n14     for(int j = 0; j < matrix2[i].length; j++)\n15     matrix2[i][j] = input.nextInt();\n16  //3.输出二维数组所有元素\n17  System.out.println("matrix1:");\n18  for(int i = 0; i < matrix1.length; i++) {\n19     for(int j = 0; j < matrix1[i].length; j++)\n20     System.out.print(matrix1[i][j] + " ");\n21     System.out.println();\n22  }\n23  System.out.println("matrix2:");\n24  for(int i = 0; i < matrix2.length; i++) {\n25     for(int j = 0; j < matrix2[i].length; j++)\n26     System.out.print(matrix2[i][j] + " ");\n27     System.out.println();\n28  }\n29  //4.按列求和\n30  for(int j = 0; j < matrix1[0].length; j++) {\n31     int total = 0;\n32     for(int i = 0; i < matrix1.length; i++)\n33     total += matrix1[i][j];\n34     System.out.printf("matrix1 第%d 列的和是%d\\n", j, total);\n35  }\n36  //5.按行求和，并输出哪一行和最大\n37  int maxRow = 0;\n38  int indexOfMaxRow = 0;\n39            for(int i = 0; i < matrix1[0].length; i++) {\n40                 int total = 0;\n41                 for(int j = 0; j < matrix1.length; j++)\n42                    total += matrix1[i][j];\n43                 if(total > maxRow) {\n44                    maxRow = total;\n45                    indexOfMaxRow = i;\n46                 }\n47            }\n48            System.out.printf("matrix1 第%d 行的和最大，和是%d\\n",\n49                    indexOfMaxRow, maxRow);\n50            //6.求二维数组所有元素的和\n51            int sum = 0;\n52            for(int i = 0; i < matrix1.length; i++)\n53                 for(int j = 0; j < matrix1[i].length; j++)\n54                    sum += matrix1[i][j];\n55            System.out.printf("matrix1 所有元素的和是%d\\n", sum);\n56            //7.随机打乱\n57            for(int i = 0; i < matrix1.length; i++)\n58                 for(int j = 0; j < matrix1[i].length; j++) {\n59                    int i1 = (int)(Math.random()*matrix1.length);\n60                    int j1 = (int)(Math.random()*matrix1[i].length);\n61                    //随机下标 i1、j1 指定元素与 i、j 指定元素交换\n62                    int temp = matrix1[i][j];\n63                    matrix1[i][j] = matrix1[i1][j1];\n64                    matrix1[i1][j1] = temp;\n65                 }\n66            //输出随机打乱后的数组\n67            System.out.println("随机打乱后 matrix1:");\n68            for(int i = 0; i < matrix1.length; i++) {\n69                 for(int j = 0; j < matrix1[i].length; j++)\n70                    System.out.print(matrix1[i][j] + " ");\n71                 System.out.println();\n72            }\n73 }\n74 }', 0, 187, 56),
