(228, 104, '程序清单 5-13　TestThreeDArray.java', '1  public class TestThreeDArray {\n2   public static void main(String[] args) {\n3     int[][][] grades = {\n4            {{45, 40}, {35, 38}, {45, 42}},\n5            {{42, 45}, {38, 40}, {47, 48}},\n6            {{39, 42}, {45, 45}, {42, 40}},\n7            {{35, 38}, {45, 47}, {48, 45}},\n8            {{50, 48}, {45, 46}, {47, 42}},\n9     };\n10    int[] total = new int[grades.length]; //保存 5 个考生的总成绩\n11    for(int i = 0; i < grades.length; i++)\n12        for(int j = 0; j < grades[i].length; j++)\n13           for(int k = 0; k < grades[i][j].length; k++)\n14           total[i] += grades[i][j][k];\n15    for(int i = 0; i < total.length; i++)\n16        System.out.printf("第%d 名考生的总分是：%d\\n",\n17           i+1, total[i]);\n18    //找出总分最高的考生\n19    int maxTotal = total[0];\n20    int maxIndex = 0;\n21    for(int i = 1; i < total.length; i++) {\n22        if(maxTotal < total[i]) {\n23           maxTotal = total[i];\n24           maxIndex = i;\n25        }\n26    }\n27    System.out.printf("被录取的是第%d 名考生，总分为：%d",\n28           maxIndex+1, total[maxIndex]);\n29 }\n30 }', 0, 190, 60),
