(231, 106, '程序清单 5-14　TestPlayingCards', '1  public class TestPlayingCards {\n2    public static void main(String[] args) {\n3      int[] cards = new int[52];\n4      String[] kinds = {"黑桃", "红桃", "梅花", "方块"};\n5      String[] values = {"Ace", "2", "3", "4", "5", "6", "7", "8", "9",\n6      "10", "Jack", "Queen", "King"};\n7      // 初始化数组\n8      for (int i = 0; i < cards.length; i++)\n9         cards[i] = i;\n10     // 混洗扑克牌\n11     for (int i = 0; i < cards.length; i++) {\n12        int index = (int)(Math.random() * cards.length);\n13        int temp = cards[i];\n14        cards[i] = cards[index];\n15        cards[index] = temp;\n16     }\n17     // 给 3 名选手各发 5 张牌\n18     int[][] playerCards= new int[3][5];\n19     int a=0, b=0, c=0;\n20     for (int i = 0; i < 15; i++) {\n21        switch(i % 3) {\n22           case 0: {\n23                   playerCards[0][a] = cards[i];\n24                   a++;\n25                   break;\n26                   }\n27           case 1: {\n28                   playerCards[1][b] = cards[i];\n29                   b++;\n30                   break;\n31                   }\n32           case 2: {\n33                   playerCards[2][c] = cards[i];\n34                   c++;\n35                   break;\n36           }\n37        }\n38     }\n39     //输出每个玩家手中的牌\n40     for(int i = 0; i < playerCards.length; i++) {\n41        System.out.printf("玩家%d 的牌：", (i+1));\n42        for(int j = 0; j < playerCards[i].length; j++) {\n43           String kind = kinds[playerCards[i][j]/13];\n44           String value = values[playerCards[i][j] % 13];\n45           System.out.print(kind + value + " ");\n46        }\n47        System.out.println();\n48     }\n49   }\n50 }', 0, 191, 63),
(232, 106, '程序清单 5-14 运行结果', '玩家 1 的牌：0->黑桃 Ace 22->红桃 10 51->方块 King 19->红桃 7 38->梅花 King\n玩家 2 的牌：33->梅花 8 36->梅花 Jack 42->方块 4 27->梅花 2 10->黑桃 Jack\n玩家 3 的牌：31->梅花 6 37->梅花 Queen 49->方块 Jack 23->红桃 Jack 44->方块 6', 0, 192, 64),
(233, 107, '程序清单 5-15　PhaseExam.java', '1  public class PhaseExam {\n2    public static void main(String[] args) {\n3      char[] answers = {\'A\', \'B\',\'A\',\'C\',\'C\',\n4              \'D\',\'B\',\'C\',\'B\',\'A\'};                       //存储正确答案\n5      String[] stuIDs = new String[10]; //存储学号\n6      char[][] stuAnswers = {                             //存储每名学生的答题表\n7              {\'A\',\'B\',\'A\',\'C\',\'D\',\'D\',\'B\',\'B\',\'B\',\'A\'},\n8              {\'A\',\'B\',\'A\',\'B\',\'C\',\'B\',\'B\',\'D\',\'A\',\'B\'},\n9              {\'A\',\'A\',\'C\',\'B\',\'A\',\'A\',\'C\',\'A\',\'B\',\'A\'},\n10             {\'B\',\'B\',\'C\',\'C\',\'C\',\'A\',\'B\',\'B\',\'C\',\'A\'},\n11             {\'A\',\'B\',\'A\',\'C\',\'C\',\'D\',\'A\',\'C\',\'B\',\'D\'},\n12             {\'B\',\'B\',\'A\',\'C\',\'C\',\'D\',\'B\',\'C\',\'B\',\'A\'},\n13             {\'A\',\'B\',\'A\',\'C\',\'C\',\'D\',\'C\',\'C\',\'B\',\'B\'},\n14             {\'A\',\'B\',\'A\',\'C\',\'B\',\'D\',\'B\',\'B\',\'C\',\'A\'},\n15             {\'A\',\'B\',\'B\',\'C\',\'B\',\'D\',\'B\',\'C\',\'B\',\'A\'},\n16             {\'B\',\'B\',\'B\',\'C\',\'D\',\'D\',\'B\',\'C\',\'B\',\'A\'} };\n17       int[] scores = new int[stuIDs.length]; //存储成绩\n18       //初始化学号数组\n19       for(int i = 0; i < stuIDs.length - 1; i++)\n20          stuIDs[i] = "20230" + (i+1);\n21       stuIDs[9] = "202310";\n22       //阅卷评分,并输出结果\n23       for(int i = 0; i < stuAnswers.length; i++) {\n24          for(int j = 0; j < stuAnswers[i].length; j++)\n25          if(stuAnswers[i][j] == answers[j]) //答案正确，分值+2\n26                              scores[i] += 2;\n27          System.out.printf("学号：%s, 成绩：%d\\n",\n28                              stuIDs[i], scores[i]);\n29       }\n30     }\n31   }', 0, 193, 65),
