(145, 98, 92, 'System.arraycopy', '从源数组指定位置把若干元素复制到目标数组指定位置，形参为 Object 类型。', 184, 2),
(146, 100, 93, 'int[][]', '二维数组类型的声明形式，两对方括号对应行、列两个下标维度。', 185, 1),
(147, 101, 94, 'scores[0].length', '取二维数组中第一个一维数组的长度，即列方向元素个数。', 185, 1),
(148, 102, 95, 'new int[4][]', '只指定第一维长度创建锯齿数组，各行再用 new int[k] 分别创建。', 186, 1),
(149, 106, 98, '%', '取余运算：cardValue % 13 得到牌面值在 values 数组中的下标。', 193, 1),
