(151, 107, 99, 'char[][]', '二维字符数组存储每名学生的答题表，逐行与正确答案数组比对评分。', 194, 1),
(152, 108, 100, 'double[][]', '二维数组形参与返回值类型，用 a.length、a[0].length 确定行列循环范围。', 196, 1),
(153, 110, 101, 'equals()', '比较两个字符串内容是否相等，与比较对象引用的 == 运算符不同。', 197, 1),
(154, 110, 101, 'new String()', '用构造方法创建字符串对象，总在堆中新建对象，效率低于字面量方式。', 197, 2),
(155, 112, 103, '"""', '文本块的定界符，开始的三个双引号必须单独成行。', 203, 1),
(156, 114, 104, '\\d', '正则元字符，匹配单个数字字符，相当于 [0-9]；写在字符串中要写成 \\\\d。', 204, 1),
(157, 114, 104, '\\p{P}', '正则元字符，匹配一个标点字符，常用于拆分与替换。', 204, 2),
(158, 114, 104, '^', '正则元字符，指定起始字符。', 204, 3),
(159, 114, 104, '$(正则行尾锚)', '正则元字符，指定结束字符。', 204, 4),
(160, 114, 104, '{n,m}', '正则量词，指定至少 n 个但不多于 m 个匹配。', 204, 5),
(161, 114, 104, 'matches', '判断整个字符串是否匹配给定正则表达式，不是局部匹配。', 205, 6),
(162, 115, 105, 'split', '按正则表达式的匹配项拆分字符串，返回字符串数组。', 205, 1),
(163, 115, 105, 'limit', 'split 的第二个参数，限定模式匹配次数，决定结果数组长度。', 205, 2),
(164, 116, 106, 'replaceAll', '把所有匹配正则的子串替换为指定字符串，支持 $1、$2 分组引用。', 206, 1),
(165, 116, 106, 'replaceFirst', '只替换第一个匹配正则的子串，返回新的字符串。', 206, 2),
(166, 116, 106, 'replace', '按字面字符序列进行替换，不支持正则表达式。', 206, 3),
(167, 118, 107, 'charAt()', '取指定位置的字符，回文判断中用于首尾字符两两比较。', 207, 1),
