INSERT INTO `knowledge_difficult_point` (`id`, `chapter_id`, `description`, `type`, `page`, `page_order`) VALUES
(51, 90, '数组长度通常应是正整数：Java 编译器不检查长度是否为正，长度为负时在运行时抛出 NegativeArraySizeException，长度为 0 时数组不含任何元素，访问元素立即下标越界。', 1, 166, 1),
(52, 91, '下标合法范围是 0 到 length-1：把循环条件写成 i <= array.length 或用 array.length 直接作下标都会产生 ArrayIndexOutOfBoundsException，用 length 控制循环上界可避免越界。', 1, 167, 1),
(53, 91, '数组长度不可修改与数组变量重新赋值的辨析：ns = new int[]{1, 2, 3} 之后 ns.length 由 5 变为 3，并不是数组长度被改变，而是引用改指向了另一个更小的数组，原数组被 JVM 回收。', 3, 169, 1),
(54, 94, '把数组传给方法后，形参对元素的修改会反映到实参：实参与形参引用同一片内存区域；而 swap(int, int) 只改变形参的值拷贝，数组元素不变。本章选择题、简答题高频考查。', 2, 172, 1),
(55, 95, '折半查找的前提是数组已按升序排好：对无序数组调用 halfSearch 或 Arrays.binarySearch，结果不可预期；Arrays.binarySearch 未找到 key 时返回 (-插入点-1) 而不是-1。', 1, 177, 1),
(56, 96, '冒泡排序两层循环的边界：n 个元素最多比较 n-1 趟，内层上界是 length-i-1；写成 length-1 会重复比较已就位的有序区域甚至越界；用 flag 变量在本趟无交换时提前结束。', 2, 179, 1),
(57, 97, 'Arrays 类方法的名称与调用形式：方法都是静态的，须写 Arrays.sort(a) 或 java.util.Arrays.sort(a)；java.util.Arrays(scores)、sorts()、sortArray() 均不存在，属常见错误写法。', 1, 181, 1),
(58, 98, '浅度复制与深度复制的区别：int[] b = a 只复制引用，两变量指向同一数组，改 b 即改 a；要复制内容必须用 copyOf、copyOfRange、System.arraycopy 或循环逐元素赋值。', 3, 182, 1),
(59, 101, '二维数组创建的合法形式：int[][] d = new int[3] 是编译错误（int[] 无法转换为 int[][]）；完整矩阵用 new int[m][n]，只先建行数组用 new int[m][]。', 1, 185, 1),
(60, 102, '锯齿数组遍历的列上界：各行长度不同，内层循环必须使用 list[i].length；用固定的列数或 list.length 会让短行下标越界、长行漏访问元素。', 1, 186, 1),
(61, 110, '== 比较是否为同一对象、equals 比较内容：相同字面量因字符串常量池共享对象而 == 为 true，new String(字面量) 每次在堆中新建对象使 == 为 false，比较内容必须用 equals()。', 2, 196, 1),
(62, 112, '文本块开始的三个双引号必须单独成行：String s = """ html """; 会编译报错；文本块内的换行与引号不需要像传统字符串那样转义和拼接，缩进只保留相对缩进。', 1, 202, 1),
(63, 113, '正则表达式写在字符串里要双写反斜杠：\\d 必须写成 "\\\\d"，否则 Java 编译器把 \\d 当作非法转义序列；\\d{3}、\\p{P} 等元字符同理，是正则题最常见的失分点。', 1, 204, 1),
(64, 116, 'replace 与 replaceAll/replaceFirst 的辨析：replace(target, replacement) 按字面字符序列替换、不支持正则；replaceAll/replaceFirst 支持正则，替换串中的 $1、$2、$3 引用捕获组。', 3, 206, 1),
(65, 121, '可变长参数只能有一个且必须是最后一个参数：double… 与 double[] 被编译器视为同一类型，printMin(double…) 与 printMin(double[]) 不能同时定义，否则编译报错。', 1, 211, 1);
INSERT INTO `knowledge_exercise` (`id`, `chapter_id`, `question`, `answer`, `difficulty`, `knowledge_point`, `page`, `page_order`) VALUES
(269, 88, '1、 在 Java 程序中有定义：int x[][]=new int[4][5];则 x.length 和 x[3].length 的值分别是（ ）\n(A) 4 和 5　(B) 5 和 4　(C) 4 和 3　(D) 5 和 3', '@ANS269@', 1, '@KP269@', 215, 1),
(270, 88, '2、 假定一个方法 p 有如下方法头：\n```java\npublic static int[] p()\n```\n哪个 return 语句可以用在 p()中？（ ）\n(A) return 1;　(B) return {1, 2, 3};\n(C) return int[]{1, 2, 3};　(D) return new int[]{1, 2, 3};', '@ANS270@', 1, '@KP270@', 215, 2),
(271, 88, '3、 假设 int i = 5，以下哪一项不能用作数组 double[] t = new double [100]的下标（ ）\n(A) i　(B) (int)(Math.random()* 100))\n(C) i + 10　(D) i+ 6.5', '@ANS271@', 1, '@KP271@', 215, 3),
(272, 88, '4、 若有定义：byte[] x={11, 22, 33, -66}; 其中 0≤k≤3，则对 x 数组元素错误的引用是（ ）\n(A) x[5-3]　(B) x[k]　(C) x[k+5]　(D) x[0]', '@ANS272@', 1, '@KP272@', 215, 4),
(273, 88, '5、 假定：int[] scores = {1, 20, 30, 40, 50}, 那么 java.util.Arrays.binarySearch(scores, 3) 返回的值是（ ）\n(A) 0 (B)-1 (C) 2 (D) -2', '@ANS273@', 1, '@KP273@', 215, 5),
(274, 88, '6、 下面哪个方法是对 double 型数组 scores 的排序（ ）\n(A) java.util.Arrays(scores)\n(B) java.util.Arrays.sorts(scores)\n(C) java.util.Arrays.sort(scores)\n(D) java.util.Arrays.sortArray(scores)', '@ANS274@', 1, '@KP274@', 215, 6),
(275, 88, '7、 关于数组的说法错误的是（ ）\n(A) 数组中可以存储多个数据\n(B) 数组中存储的多个数据的类型必须一致\n(C) 数组的长度一旦确定，还可以发生改变\n(D) 数组是引用类型', '@ANS275@', 1, '@KP275@', 215, 7),
